import{_ as o,C as d,o as a,c as l,a2 as t,b as s,w as i,a as c,E as n,a3 as p}from"./chunks/framework.DZUUNQ77.js";const B=JSON.parse('{"title":"AtomicFile · 原子文件","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helper/utils/atomic-file.md","filePath":"reference/helper/utils/atomic-file.md","lastUpdated":1784063681000}'),A={name:"reference/helper/utils/atomic-file.md"};function m(E,e,h,u,b,F){const r=d("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t(`<h1 id="atomicfile-·-原子文件" tabindex="-1">AtomicFile · 原子文件 <a class="header-anchor" href="#atomicfile-·-原子文件" aria-label="Permalink to &quot;AtomicFile · 原子文件&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/helper/utils/AtomicFile.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/helper/utils/AtomicFile.java</code></a></p></div><p><code>AtomicFile</code> 对应 AOSP 同名工具，提供「写临时文件 + rename」的原子写入语义，保证写一半崩溃不会损坏原文件。它本身不存数据，只是包了一个 <code>File</code> 并提供安全读写流程。</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>AtomicFile(File baseName)</code></td><td>绑定目标文件</td></tr><tr><td><code>getBaseFile()</code></td><td>取底层 <code>File</code></td></tr><tr><td><code>startWrite()</code></td><td>开始写，返回 <code>FileOutputStream</code>（实际指向 <code>.new</code> 临时文件）</td></tr><tr><td><code>finishWrite(FileOutputStream str)</code></td><td>写成功，把临时文件 rename 成正式文件</td></tr><tr><td><code>failWrite(FileOutputStream str)</code></td><td>写失败，删除临时文件</td></tr><tr><td><code>openRead()</code> / <code>readFully()</code></td><td>读取正式文件</td></tr><tr><td><code>delete()</code></td><td>删除正式与临时文件</td></tr><tr><td><code>truncate()</code></td><td>清空文件</td></tr></tbody></table><h2 id="原子写入流程" tabindex="-1">原子写入流程 <a class="header-anchor" href="#原子写入流程" aria-label="Permalink to &quot;原子写入流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startWrite()  →  写到  baseName.new</span></span>
<span class="line"><span>finishWrite() →  baseName.new  rename→  baseName   （原子操作）</span></span>
<span class="line"><span>failWrite()   →  删除  baseName.new</span></span></code></pre></div><p><code>rename</code> 在同一文件系统上是原子的，所以要么看到完整的旧文件、要么看到完整的新文件，绝不会出现半新半旧的损坏态。</p><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>各 <code>PersistenceLayer</code>（见 <a href="./../helper-top">helper 顶层</a>）持久化关键配置时用它：</p><ul><li><code>PackagePersistenceLayer</code> —— 虚拟安装的包列表</li><li><code>DeviceInfoPersistenceLayer</code> —— 伪造的设备信息</li><li>其他账户/权限配置</li></ul><p>server 进程崩溃重启后能读到上一次完整状态。</p><h2 id="原子写入时序" tabindex="-1">原子写入时序 <a class="header-anchor" href="#原子写入时序" aria-label="Permalink to &quot;原子写入时序&quot;">​</a></h2>`,13)),(a(),s(p,null,{default:i(()=>[n(r,{id:"mermaid-128",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20PL%20as%20PersistenceLayer%0A%20%20participant%20AF%20as%20AtomicFile%0A%20%20participant%20FS%20as%20%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%0A%20%20PL-%3E%3EAF%3A%20startWrite()%0A%20%20AF-%3E%3EFS%3A%20%E5%88%9B%E5%BB%BA%20baseName.new%0A%20%20AF--%3E%3EPL%3A%20FileOutputStream(%E6%8C%87%E5%90%91%20.new)%0A%20%20PL-%3E%3EAF%3A%20%E5%86%99%E6%95%B0%E6%8D%AE%E5%88%B0%E6%B5%81%0A%20%20alt%20%E5%86%99%E6%88%90%E5%8A%9F%0A%20%20%20%20PL-%3E%3EAF%3A%20finishWrite()%0A%20%20%20%20AF-%3E%3EFS%3A%20rename%20.new%20%E2%86%92%20baseName%20(%E5%8E%9F%E5%AD%90)%0A%20%20%20%20Note%20over%20FS%3A%20%E8%A6%81%E4%B9%88%E6%97%A7%E6%96%87%E4%BB%B6%20%E8%A6%81%E4%B9%88%E6%96%B0%E6%96%87%E4%BB%B6%0A%20%20else%20%E5%86%99%E5%A4%B1%E8%B4%A5%2F%E5%B4%A9%E6%BA%83%0A%20%20%20%20PL-%3E%3EAF%3A%20failWrite()%0A%20%20%20%20AF-%3E%3EFS%3A%20%E5%88%A0%E9%99%A4%20.new%0A%20%20%20%20Note%20over%20FS%3A%20%E5%8E%9F%E6%96%87%E4%BB%B6%E5%AE%8C%E5%A5%BD%0A%20%20end%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p><code>rename</code> 在同一文件系统上是原子的——绝不会出现半新半旧的损坏态。</p><div class="tip custom-block"><p class="custom-block-title">openAppend 已废弃</p><p><code>openAppend</code> 标了 <code>@Deprecated</code>，因为追加写破坏原子性——追加过程中崩溃会留下不完整尾部。</p></div><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>持久化层见 <a href="./../helper-top">helper 顶层</a>。</li><li>与 <a href="./fast-xml-serializer"><code>FastXmlSerializer</code></a> 配合序列化。</li></ul>',4))])}const _=o(A,[["render",m]]);export{B as __pageData,_ as default};
